presets.css:
/* ===== 变量 ===== */
:root{
  --line-me:#8de28a;      /* 我方气泡 */
  --line-them:#fff;       /* char 气泡 */
  --line-text:#111;
  --line-sub:rgba(0,0,0,.5);
  --line-bar:rgba(255,255,255,.35);
  --line-input:#eceef2;
}

/* ===== 顶栏：返回键+名字靠左，右侧 装饰/心声/设置 ===== */
.chat-thread-top{padding-top:env(safe-area-inset-top,0);background:var(--line-bar);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.chat-thread-pill{height:18px;padding:0 10px;border:0;border-radius:0;box-shadow:none;
  background:transparent;display:flex;align-items:center}
.chat-back{background:none;border:0;color:var(--line-text)}
.chat-back svg path{stroke-width:2.4}
.chat-thread-center{flex:1;text-align:left;margin-left:6px}
.chat-thread-center h2{font-size:20px;font-weight:700;color:var(--line-text);margin:0}
.chat-thread-head-actions{display:flex;align-items:center;gap:6px}
/* 装饰：放大镜 */
.chat-thread-head-actions::before{content:"";width:24px;height:24px;margin-right:6px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><path d='M16.5 16.5L21 21'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><path d='M16.5 16.5L21 21'/></svg>") center/contain no-repeat}
.chat-thread-head-xinsheng,.chat-thread-head-more{width:32px;height:32px;padding:0;border:0;background:none;
  display:flex;align-items:center;justify-content:center}
.chat-thread-head-xinsheng svg,.chat-thread-head-more svg{display:none}
/* 心声：电话形状 */
.chat-thread-head-xinsheng::before{content:"";width:24px;height:24px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><path d='M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'><path d='M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z'/></svg>") center/contain no-repeat}
/* 对话设置：三横线 */
.chat-thread-head-more::before{content:"";width:24px;height:24px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M4 7h16M4 12h16M4 17h16'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'><path d='M4 7h16M4 12h16M4 17h16'/></svg>") center/contain no-repeat}

/* ===== 日期胶囊 ===== */
.chat-msg-timestamp{display:table;margin:14px auto 8px;padding:2px 12px;border-radius:12px;
  background:rgba(0,0,0,.25);color:#fff;font-size:12px}

/* ===== 消息行 ===== */
.chat-msg{display:flex;align-items:flex-end;gap:8px;padding:0 12px;margin:6px 0}
.chat-msg.is-me{justify-content:flex-end}
.chat-msg.is-them .chat-ava{align-self:flex-start;border-radius:50%}
.chat-msg-name{display:none}            /* 不要 char 名字 */
.chat-msg-body{max-width:78%}
.chat-swipe-content{display:flex;align-items:flex-end;gap:6px}

/* 时间：气泡外侧；我方在左，下方 */
.chat-msg-time{display:block;font-size:8px;line-height:1.3;color:var(--line-sub);white-space:nowrap;margin:0}
.chat-msg.is-me .chat-msg-time{order:-1;text-align:right}
.chat-msg.is-me .chat-msg-time::before{content:"既読";display:block}   /* 想要日文就改成 既読 */
/* char 也要已读字样时取消下一行注释 */
/* .chat-msg.is-them .chat-msg-time::before{content:"既読";display:block} */

/* ===== 气泡  ===== */
.chat-bubble{position:relative;padding:6px 10px;border-radius:20px;font-size:12px;line-height:1.3;color:var(--line-text);border:0;box-shadow:none}
.chat-msg.is-me .chat-bubble{background:var(--line-me)}
.chat-msg.is-them .chat-bubble{background:var(--line-them)}
.chat-bubble-primary{margin:0}

/* ===== 引用回复气泡：头像+名字+引用内容 / 分隔线 / 回复 ===== */
.chat-bubble.has-inner-quote{padding:0;min-width:62vw}
.chat-qq-quote{display:grid;grid-template-columns:30px 1fr;column-gap:8px;align-items:center;
  width:100%;text-align:left;margin:0;padding:12px 14px 10px;border:0;border-radius:0;background:none;
  border-bottom:1px solid rgba(0,0,0,.12)}
.chat-qq-quote::before{content:"";grid-row:1 / span 2;width:30px;height:30px;border-radius:50%;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.8' stroke-linecap='round'><circle cx='12' cy='8' r='4'/><path d='M4 21c0-4 4-6 8-6s8 2 8 6'/></svg>") center/62% no-repeat,#b9e3d0}
.chat-qq-quote-name{grid-column:2;font-size:13px;font-weight:700;color:var(--line-text)}
.chat-qq-quote-text{grid-column:2;font-size:13px;color:var(--line-sub);display:-webkit-box;
  -webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.has-inner-quote .chat-bubble-primary{padding:12px 14px}

/* ===== 底栏：+ / 装饰相机 / 装饰相册 / Aa输入框(内含装饰表情) / 语音 ===== */
.chat-compose{padding:6px 10px calc(env(safe-area-inset-bottom,0px) + 6px);background:var(--line-bar);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.chat-compose-field,.chat-compose-bar{display:flex;align-items:center;gap:4px;padding:0;border:0;border-radius:0;box-shadow:none;background:none}
.chat-compose-plus-wrap{order:1}
.chat-compose-plus{width:36px;height:36px;padding:0;border:0;background:none;color:var(--line-text)}
.chat-compose-plus svg{width:26px;height:26px;stroke-width:2}
/* 装饰：相机 */
.chat-compose-bar::before{content:"";order:2;width:36px;height:36px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round'><path d='M4 8h3l1.5-2h7L17 8h3v11H4z'/><circle cx='12' cy='13.5' r='3.5'/></svg>") center/26px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round'><path d='M4 8h3l1.5-2h7L17 8h3v11H4z'/><circle cx='12' cy='13.5' r='3.5'/></svg>") center/26px no-repeat}
/* 装饰：相册 */
.chat-compose-bar::after{content:"";order:3;width:36px;height:36px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round' stroke-linecap='round'><rect x='4' y='5' width='16' height='14' rx='2'/><path d='M4 16l5-5 4 4 3-3 4 4'/></svg>") center/26px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linejoin='round' stroke-linecap='round'><rect x='4' y='5' width='16' height='14' rx='2'/><path d='M4 16l5-5 4 4 3-3 4 4'/></svg>") center/26px no-repeat}
/* 输入框：灰胶囊 + Aa 占位 + 右侧装饰表情 */
.chat-compose-input{order:4;flex:1;min-height:36px;border:0;border-radius:20px;padding:7px 40px 7px 14px;
  color:var(--line-text);font-size:16px;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23666' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='12' r='9'/><path d='M8 14c1 1.5 2.5 2 4 2s3-.5 4-2M9 10h.01M15 10h.01'/></svg>") right 10px center/22px no-repeat,var(--line-input)}
.chat-compose-input:placeholder-shown{
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23666' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='12' r='9'/><path d='M8 14c1 1.5 2.5 2 4 2s3-.5 4-2M9 10h.01M15 10h.01'/></svg>") right 10px center/22px no-repeat,
  url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='30' height='20'><text x='0' y='16' font-size='17' fill='%23aaa' font-family='sans-serif'>Aa</text></svg>") left 14px center/auto 20px no-repeat,var(--line-input)}
.chat-compose-input::placeholder{color:transparent}
/* 语音：麦克风 */
.chat-compose-icon.is-voice{order:5;width:36px;height:36px;padding:0;border:0;background:none;display:flex;align-items:center;justify-content:center}
.chat-compose-icon.is-voice svg{display:none}
.chat-compose-icon.is-voice::before{content:"";width:26px;height:26px;background:var(--line-text);
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><rect x='9' y='3' width='6' height='11' rx='3'/><path d='M5 11a7 7 0 0 0 14 0M12 18v3'/></svg>") center/contain no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.9' stroke-linecap='round'><rect x='9' y='3' width='6' height='11' rx='3'/><path d='M5 11a7 7 0 0 0 14 0M12 18v3'/></svg>") center/contain no-repeat}
/* 发送键/回复键隐藏；输入文字后才显示发送键（想完全隐藏就删掉最后两条） */
.chat-compose-icon.is-reply,.chat-compose-icon.is-send{display:none}
.chat-compose-bar:has(.chat-compose-input:not(:placeholder-shown)) .chat-compose-icon.is-send{display:flex;order:6}
.chat-compose-bar:has(.chat-compose-input:not(:placeholder-shown)) .chat-compose-icon.is-voice{display:none}

/* ===== 顶栏：左右贴边、整体上提 ===== */
:root{--top-lift:60px}   /* 还嫌低就改成 8px / 16px，往上提 */

.chat-thread-top{
  margin:0 !important;
  margin-top:calc(var(--top-lift) * -1) !important;
  left:0 !important; right:0 !important;
  width:100% !important; max-width:none !important;
  padding:env(safe-area-inset-top,0px) 0 0 !important;
  border-radius:0 !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  background:var(--line-bar) !important;
  box-sizing:border-box;
}
.chat-thread-pill{
  margin:0 !important;
  width:100% !important; max-width:none !important;
  height:34px !important;
  padding:0 12px !important;      /* 内部留一点边，图标不贴屏幕边；要完全贴就改 0 */
  border-radius:0 !important;
  box-shadow:none !important;
  background:transparent !important;
  box-sizing:border-box;
}

/* ===== 已读+时间：用户在气泡左，char 在气泡右 ===== */
.chat-msg .chat-msg-body .chat-swipe-content{
  display:flex !important;
  flex-direction:row !important;
  align-items:flex-end !important;
  gap:6px !important;
}
.chat-msg .chat-msg-body{flex:0 1 auto !important;width:auto !important}
.chat-msg .chat-msg-time{
  position:static !important;
  inset:auto !important;
  transform:none !important;
  margin:0 !important;
  display:block !important;
  white-space:nowrap;
  line-height:1.3;
}
/* 用户：左侧，右对齐 */
.chat-msg.is-me .chat-msg-time{order:-1 !important;text-align:right !important}
.chat-msg.is-me .chat-msg-time::before{content:"既読";display:block}
/* char：右侧，左对齐，也显示已读 */
.chat-msg.is-them .chat-msg-time{order:2 !important;text-align:left !important}
.chat-msg.is-them .chat-msg-time::before{content:"既読";display:block}

/* ===== char 气泡与头像垂直齐平 ===== */
.chat-msg.is-them{align-items:center !important}
.chat-msg.is-them .chat-ava{align-self:center !important}

.chat-thread-top::before,.chat-thread-top::after,
.chat-thread-pill::before,.chat-thread-pill::after{display:none !important}
.chat-thread-pill{backdrop-filter:none !important;-webkit-backdrop-filter:none !important;filter:none !important}

.chat-msg.has-quote .chat-msg-body{max-width:calc(100vw - 64px) !important}
.chat-bubble.has-inner-quote{min-width:0 !important;width:62vw !important;max-width:100% !important;flex:0 1 auto}
.chat-qq-quote{min-width:0}
.chat-qq-quote-text{word-break:break-all}

:root{--read-size:8px}
.chat-msg.is-me .chat-msg-time::before,
.chat-msg.is-them .chat-msg-time::before{font-size:var(--read-size);line-height:1.2}

.chat-thread-center h2{font-size:16px !important}

.chat-msg.is-me .chat-swipe-content{gap:2px !important}
.chat-msg.is-me .chat-msg-time{margin:0 !important;padding:0 !important}
.chat-msg.is-me .chat-bubble{margin-left:0 !important}

.chat-msg.is-them .chat-swipe-content{gap:2px !important}
.chat-msg.is-them .chat-msg-time{margin:0 !important;padding:0 !important}
.chat-msg.is-them .chat-bubble{margin-left:0 !important}

.chat-thread-center{margin-left:-10px !important}

/* ===== char 气泡下移旋钮 ===== */
:root{--them-down:6px}   /* 往下调就加大，比如 10px */
.chat-msg.is-them .chat-msg-body{position:relative !important;top:var(--them-down) !important}

/* ===== 贴边：char 靠左，user 靠右 ===== */
:root{--shift-them:10px;--shift-me:10px}   /* 数字越大越贴边 */

.chat-msg{padding-left:0 !important;padding-right:0 !important}
.chat-msg.is-them{position:relative !important;left:calc(var(--shift-them) * -1) !important}
.chat-msg.is-me{position:relative !important;left:var(--shift-me) !important}

/* ===== 关联表情：单独占一行，在输入栏上方 ===== */
.chat-compose,
.chat-compose-field{display:flex !important;flex-direction:column !important;align-items:stretch !important}
.chat-compose-field{gap:6px !important}

.chat-compose-sticker-suggest{
  position:static !important;
  order:-1;
  display:flex !important;
  align-items:center;
  gap:8px;
  width:100%;
  margin:0 0 6px;
  padding:0 4px;
  background:transparent !important;
  box-sizing:border-box;
}
.chat-compose-sticker-suggest-item{
  flex:none;
  width:52px;height:52px;
  padding:0;border:0;border-radius:14px;
  overflow:hidden;background:transparent;
}
.chat-compose-sticker-suggest-item img{
  width:100%;height:100%;
  object-fit:cover;display:block;
}
